// ---- Spacing: Grid utility ----

// Column counts, gutter and breakpoints are derived from foundation/gridSystem so this
// class and theme.breakpoints stay in lockstep. The media queries use the em breakpoints
// directly (not a px conversion) so .zimm-grid switches at the same viewport widths as
// Chakra's responsive props AND scales with the user's font size — an em query at 48em
// shifts with zoom/root-font changes, a fixed 768px query would not (WCAG 1.4.4).
const zimmGrid: SystemStyleObject = {
  display: 'grid',
  gridTemplateColumns: `repeat(${grid.columns.base}, 1fr)`,
  columnGap: grid.columnGap,
  paddingInline: 'var(--zimm-grid-margin-mobile)',
  [`@media (min-width: ${breakpoints.md})`]: {
    gridTemplateColumns: `repeat(${grid.columns.md}, 1fr)`,
    paddingInline: 'var(--zimm-grid-margin-tablet)',
  },
  [`@media (min-width: ${breakpoints.xl})`]: {
    gridTemplateColumns: `repeat(${grid.columns.xl}, 1fr)`,
    paddingInline: 'var(--zimm-grid-margin-desktop)',
  },
};

// ---- Layout: main content area ----

// Base SFCC's own _app/index.jsx renders <Box as="main" id="app-main"> with no styling hook —
// no theme part, no Chakra recipe, just plain inline props — and this project deliberately
// hasn't forked _app.jsx. Targeting the stable #app-main id here applies the same shared
// --zimm-grid-margin-*/--zimm-grid-max-width tokens (gridSystem.ts) as header
// (header/index.tsx's HEADER_CONTENT_SX) and footer (footer.css.ts's `container`/`contentRow`/
// `logo` parts) without that fork — one place controls all three.
const zimmAppMain: SystemStyleObject = {
  maxWidth: 'var(--zimm-grid-max-width)',
  marginLeft: 'auto',
  marginRight: 'auto',
  paddingLeft: 'var(--zimm-grid-margin-mobile)',
  paddingRight: 'var(--zimm-grid-margin-mobile)',
  [`@media (min-width: ${breakpoints.xl})`]: {
    paddingLeft: 'var(--zimm-grid-margin-desktop)',
    paddingRight: 'var(--zimm-grid-margin-desktop)',
  },
};

// ---- Form field classes ----
// Shared flush-border row + native-control base styles, consolidated upstream in
// tokens/form-fields.css from zimm-text-input (flush variant), zimm-select and
// zimm-search. Each component still owns its own error state and its native
// control's disabled text colour — those genuinely differ per component and were
// deliberately not unified upstream.

const zimmFormRow: SystemStyleObject = {
  display: 'flex',
  alignItems: 'center',
  gap: 'var(--zimm-scale-xs)',
  borderBottom: 'var(--zimm-border-width-default) solid var(--zimm-color-border-forms)',
  padding: 'var(--zimm-scale-2xs) 0',
  minHeight: '36px',
  transition:
    'border-color var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard), box-shadow var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard)',
  _hover: {
    borderBottomColor: 'var(--zimm-color-text-default)',
  },
  _focusWithin: {
    borderBottomColor: 'var(--zimm-color-text-default)',
    boxShadow: '0 1px 0 0 var(--zimm-color-text-default)',
  },
};

const zimmFormRowDisabled: SystemStyleObject = {
  // color-mix is Baseline 2023 (Chrome 111+, Safari 16.2+, Firefox 113+).
  borderBottomColor: 'color-mix(in srgb, var(--zimm-color-grey-300) 50%, transparent)',
  pointerEvents: 'none',
};

const zimmFormRowInverse: SystemStyleObject = {
  borderBottomColor: 'var(--zimm-color-grey-white)',
  _hover: {
    borderBottomColor: 'var(--zimm-color-grey-white)',
  },
  _focusWithin: {
    borderBottomColor: 'var(--zimm-color-grey-white)',
    boxShadow: '0 1px 0 0 var(--zimm-color-grey-white)',
  },
};

const zimmFormControl: SystemStyleObject = {
